
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mbeef_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mbeef", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.632145548077604e+00, -4.543107166863262e+00, -4.418503126770283e+00, -4.246237501015746e+00, -4.012240231139860e+00, -3.702405398824099e+00, -3.307051073291710e+00, -2.828425409015610e+00, -2.284130832773509e+00, -1.642782032566896e+00, -9.994939308327245e-01, -6.833606181736419e-01, -6.304091337501357e-01, -5.341843086971860e-01, -3.806085086443754e-01, -2.218467027630403e-01, -1.008048608904740e-01, -3.368064892015269e-02, -6.895417154931634e-03, -7.722688960294654e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


